parameters.jsCode:
// Central run config. Azusa CA = 34.1336, -117.9075; 40km ~ 25 miles.
//
// We want whoever can APPROVE a workflow, not whoever would use it. Apollo has
// two ways to express that and they are not equally good:
//
//   person_titles      free text, matched loosely. Asking for the nine titles
//                      this used to list returned 40% "Office Manager" on the
//                      live LA personal-injury query - people who recommend,
//                      not people who sign.
//   person_seniorities Apollo's own normalised buckets. The same query with
//                      owner/founder/partner/c_suite returned partners,
//                      founders and CEOs, and 10/10 owners on home services.
//
// So seniority, not titles. excludeTitleRe below stays as the backstop.
//
// The bands, in the order we want them: owner/founder first, then C-suite
// (the CFO counts), then partners, then directors and VPs. Directors are in
// deliberately, not as dilution - on the live LA query they surfaced a
// "Director of Intake and Marketing" and a "Director of Marketing", who are
// the exact people who own an intake problem at a firm too big for the owner
// to answer the phone. More to the point, Vaziri Law appears ONLY through its
// directors: Apollo has no owner or partner there, so without this band that
// firm is either missed entirely or arrives as a nameless Google Maps row.
//
// Breadth here does not cost priority. Filter & Dedupe keeps ONE person per
// company and keeps the most senior, so a firm with both an owner and a
// marketing director still arrives as the owner - Brock & Gonzales returns
// four partners plus a director and comes through as the Senior Partner.
const DM_SENIORITIES = ['owner', 'founder', 'c_suite', 'partner', 'vp', 'director'];
const apolloBase = {
  person_seniorities: DM_SENIORITIES,
  // Apollo ANDs these two, and they mean different things:
  //   person_locations       - where the PERSON lives
  //   organization_locations - where their EMPLOYER is headquartered
  // We sell to a local business, so the HQ is the filter that matters. Setting
  // only person_locations (what this used to do) matches an owner who lives in
  // LA but whose practice is in Phoenix - not a prospect, and a wasted reveal
  // credit once it scored Tier 1. Person stays country-wide on purpose: an
  // owner who lives an hour outside the metro still owns the LA business.
  person_locations: ['United States'],
  organization_locations: ['Los Angeles, California, US'],
  organization_num_employees_ranges: ['2,100'],
  contact_email_status: ['verified'],
  // 50, not 25: one firm can occupy several rows of a page - Brock & Gonzales
  // returned four partners in a page of ten - and we keep one prospect per
  // company, so a small page yields far fewer distinct businesses than its
  // size suggests. Search costs no Apollo credits; only the reveal does.
  per_page: 50,
  page: 1,
};
return [{
  json: {
    currentYear: new Date().getFullYear(),
    maxNewPerRun: 50,
    maxPerVertical: 17,
    // Apollo credits per run. The installer raises this when a key is present
    // (APOLLO_REVEALS, default 25) - 12 was sized for a free-tier credit
    // ceiling that does not exist, because the free plan has no API at all.
    maxRevealsPerRun: 12,
    // Set by the installer from whether APOLLO_KEY is configured - do NOT flip
    // this by hand. True with no credential fails every Apollo node mid-run,
    // after the SerpAPI branch has already been skipped. Apollo's free plan
    // has no API access at all, so a key means a paid plan.
    useApollo: false,
    // 'content|editor|publish' catches trade media, which a company-name regex
    // cannot: 'Spa & Beauty Today' looks exactly like a med spa until you read
    // the title beside it, Chief Content Officer. Whoever runs a publication is
    // not buying missed-call recovery for a clinic.
    // 'chief content', not bare 'content': the rule is here to catch trade
    // media ('Spa & Beauty Today', Chief Content Officer), and a bare match
    // would also throw away a Director of Content Marketing - who is a buyer.
    excludeTitleRe: 'receptionist|paralegal|assistant|chief content|content officer|editor-in-chief|publisher',
    // Everything after 'lead gen' came from contaminants seen in live Apollo
    // results: suppliers and distributors, dental software ('DDS Cloud'), a
    // telecom company, trade media ('Spa & Beauty Today'). They sell INTO
    // our verticals, so they carry the same tags and survive every filter
    // upstream of here.
    excludeCompanyRe: 'marketing|agency|agencies|automation|\\bai\\b|artificial intelligence|software|saas|consult|growth partner|lead gen|supplies|\\bsupply\\b|wholesale|distribut|telecom|networking|\\bcloud\\b|\\blabs\\b|magazine|association',
    verticals: [
      {
        vertical: 'law_firm',
        apolloBody: { ...apolloBase, q_organization_keyword_tags: ['personal injury law'] },
        serpQuery: 'personal injury law firm near Azusa, CA',
      },
      {
        vertical: 'medical',
        // 'dental practice' / 'medical clinic' matched the wrong side of the
        // market. On the live query 8 of 10 results were vendors TO practices
        // - a dental supply company, dental software, a dental AI startup, a
        // telecom firm - because Apollo tags a company with the market it
        // sells into as readily as with what it is. Naming what the business
        // IS fixed it: 8 of 10 became owner-dentists at real practices, and
        // the pool grew from 38 to 83. NAICS codes 6211/6212 were tried and
        // were worse still, returning venture-backed health tech.
        apolloBody: { ...apolloBase, q_organization_keyword_tags: ['dentist', 'dental office', 'orthodontist', 'family dentistry', 'cosmetic dentistry', 'med spa', 'medical spa', 'chiropractic clinic', 'physical therapy clinic', 'urgent care'] },
        serpQuery: 'dentist med spa clinic near Azusa, CA',
      },
      {
        vertical: 'home_services',
        apolloBody: { ...apolloBase, q_organization_keyword_tags: ['plumbing', 'hvac', 'electrical contractor'] },
        serpQuery: 'plumber hvac electrician near Azusa, CA',
      },
    ],
  },
}];

// One item per vertical carrying the API bodies + dedupe sets.
const cfg = $('Run Config').first().json;
const norm = (d) => String(d || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].trim();
const digits = (p) => String(p || '').replace(/\D/g, '').slice(-10);
const knownDomains = [];
const knownPhones = [];
for (const i of $('Get Existing Prospects').all()) {
  const d = norm(i.json && i.json.domain);
  if (d) knownDomains.push(d);
  const p = digits(i.json && i.json.contact_phone);
  if (p) knownPhones.push(p);
}
return cfg.verticals.map((v) => ({
  json: {
    vertical: v.vertical,
    apolloBody: v.apolloBody,
    serpQuery: v.serpQuery,
    knownDomains,
    knownPhones,
    maxPerVertical: cfg.maxPerVertical,
    useApollo: cfg.useApollo === true,
    excludeTitleRe: cfg.excludeTitleRe,
    excludeCompanyRe: cfg.excludeCompanyRe,
  },
}));

// Merge Apollo + Places candidates for this vertical, apply hard excludes,
// dedupe against the table and within the run, cap per vertical.
const ctx = $('Per Vertical').first().json;
const norm = (d) => String(d || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].trim();
const digits = (p) => String(p || '').replace(/\D/g, '').slice(-10);
const exTitle = new RegExp(ctx.excludeTitleRe, 'i');
const exCompany = new RegExp(ctx.excludeCompanyRe, 'i');
const known = new Set(ctx.knownDomains);
const knownPh = new Set(ctx.knownPhones);
const seen = new Set();
const out = [];

let apollo = {};
try { apollo = $('Apollo People Search').first().json || {}; } catch (e) { apollo = {}; }
const apolloPeople = Array.isArray(apollo.people) ? apollo.people : [];
let places = $input.first().json || {};

// Surface SerpAPI failures loudly - swallowing them produced a 'successful'
// run that silently stored nothing. But loudly is not the same as fatally:
// while SerpAPI was the only source, throwing here was right; with Apollo on
// it threw away people Apollo had already returned. So the vertical fails only
// when BOTH sources came back empty.
let serpWarning = null;
if (places.error) {
  serpWarning = 'SerpAPI returned an error: ' + JSON.stringify(places.error).slice(0, 300);
} else if (!Array.isArray(places.local_results) || places.local_results.length === 0) {
  serpWarning = 'SerpAPI returned no local_results for query: ' + (ctx.serpQuery || '?') + ' | keys: ' + Object.keys(places).join(',');
}
if (serpWarning && apolloPeople.length === 0) {
  throw new Error(serpWarning);
}

// SerpAPI google_maps local_results indexed by domain (also enriches Apollo hits)
const localResults = Array.isArray(places.local_results) ? places.local_results : [];
const placeByDomain = {};
for (const p of localResults) {
  const d = norm(p.website);
  if (d) placeByDomain[d] = p;
}

// Who speaks for a company, when Apollo returns several of them. It returns
// a person per row, not a company: one live page of ten held four partners of
// the same firm. We keep one prospect per domain, and it used to be whichever
// Apollo happened to list first - so whether a firm was represented by its
// founder or by its office manager was luck. Rank instead, and keep the top.
// The bands, worst to best, and what each one means on a call:
//
//   owner     signs it themselves. Owner, Founder, CEO, President, Principal,
//             Managing Partner/Attorney.
//   c_suite   signs it or takes it to the owner in the same meeting. CFO, COO,
//             CMO - the CFO is on this list on purpose.
//   partner   one of several owners. Signs, usually after asking the others.
//   marketing owns the intake problem even when they do not own the company:
//             Director/VP of Marketing, Intake, Growth, Business Development,
//             Client Relations. The people the missed-call pitch lands on.
//   leader    a director or VP of something else - Operations, HR, IT. Real,
//             but they route you rather than buy.
//   staff     office/practice manager, administrator. A gatekeeper.
//   none      nobody named. The business is the contact.
//
// Order matters: 'marketing' is tested before the generic leader rule so a
// Director of Marketing does not fall through to it.
const AUTHORITY = [
  // (?<!vice ) on president: "Vice President Operations" is a department
  // lead, not an owner. A bare /president/ banded them with the founders,
  // which would spend a reveal credit and a call on the wrong person.
  ['owner',     /\bowner\b|founder|principal|(?<!vice )\bpresident\b|\bceo\b|chief executive|managing (partner|attorney|director)/],
  ['c_suite',   /\bchief\b|\bcoo\b|\bcfo\b|\bcmo\b|\bcto\b|\bcso\b/],
  ['partner',   /\bpartner\b/],
  ['marketing', /marketing|\bintake\b|growth|business development|\bbiz dev\b|client relations|revenue/],
  ['leader',    /director|\bvp\b|vice president|\bhead of\b/],
  ['staff',     /manager|administrator|coordinator/],
];
const RANK = { owner: 6, c_suite: 5, partner: 4, marketing: 3, leader: 2, staff: 1, none: 0 };
const authority = (title) => {
  const t = String(title || '').toLowerCase();
  for (const [band, re] of AUTHORITY) if (re.test(t)) return band;
  return 'staff';
};
const seniority = (title) => RANK[authority(title)];
// Who we would call this a decision maker for. A director of operations is a
// real person worth reaching, but saying they can approve a purchase would be
// a claim the data does not support.
const DECIDES = new Set(['owner', 'c_suite', 'partner', 'marketing']);

// Apollo has returned this object with the domain under `domain` and under
// `primary_domain` depending on the endpoint. Reading only one of them drops
// EVERY Apollo person on the `if (!domain) continue` below, silently, and the
// run still reports success - so read all three spellings.
const orgDomain = (org) => norm(org.primary_domain || org.domain || org.website_url);

const bestByDomain = new Map();
for (const person of apolloPeople) {
  const org = person.organization || {};
  const domain = orgDomain(org);
  const phone = digits(org.sanitized_phone || org.phone);
  if (!domain) continue;                                   // hard exclude: no website
  if (known.has(domain)) continue;                          // already in the table
  if (phone && knownPh.has(phone)) continue;                // dedupe on phone
  if (exTitle.test(person.title || '')) continue;           // not a decision maker
  if (exCompany.test(org.name || '')) continue;             // agencies/vendors/SaaS
  const emp = org.estimated_num_employees || null;
  if (emp !== null && emp < 2) continue;                    // solo, no staff
  const prev = bestByDomain.get(domain);
  if (!prev || seniority(person.title) > seniority(prev.title)) bestByDomain.set(domain, person);
}

for (const person of bestByDomain.values()) {
  const org = person.organization || {};
  const domain = orgDomain(org);
  const emp = org.estimated_num_employees || null;
  if (seen.has(domain)) continue;
  seen.add(domain);
  const place = placeByDomain[domain] || {};
  out.push({ json: {
    company_name: org.name || domain,
    vertical: ctx.vertical,
    website_url: org.website_url || 'https://' + domain,
    domain,
    contact_name: person.name || [person.first_name, person.last_name].filter(Boolean).join(' ') || null,
    contact_title: person.title || null,
    apollo_person_id: person.id || null,
    contact_authority: authority(person.title),
    decision_maker: DECIDES.has(authority(person.title)),
    city: org.city || person.city || null,
    state: org.state || person.state || 'California',
    // The person first, the switchboard second, and a label saying which one
    // this is. Storing only the org number and calling it contact_phone is how
    // "call the owner" quietly became "call the front desk".
    contact_phone: person.sanitized_phone || org.sanitized_phone || org.phone || null,
    contact_phone_source: person.sanitized_phone ? 'apollo_direct' : 'apollo_company',
    company_phone: org.sanitized_phone || org.phone || null,
    contact_linkedin_url: person.linkedin_url || null,
    employee_count: emp,
    rating: place.rating ?? null,
    review_count: place.reviews ?? null,
    source: 'apollo',
  }});
}

for (const p of localResults) {
  const domain = norm(p.website);
  const phone = digits(p.phone);
  if (!domain || known.has(domain) || seen.has(domain)) continue;
  if (phone && knownPh.has(phone)) continue;
  const name = p.title || domain;
  if (exCompany.test(name)) continue;
  seen.add(domain);
  out.push({ json: {
    company_name: name,
    vertical: ctx.vertical,
    website_url: p.website,
    domain,
    contact_name: null,
    contact_title: null,
    apollo_person_id: null,
    contact_authority: 'none',
    decision_maker: false,
    city: null,
    state: 'California',
    contact_phone: p.phone || null,
    contact_phone_source: p.phone ? 'google_places' : null,
    company_phone: p.phone || null,
    contact_linkedin_url: null,
    employee_count: null,
    rating: p.rating ?? null,
    review_count: p.reviews ?? null,
    source: 'google_places',
  }});
}

const capped = out.slice(0, ctx.maxPerVertical);
return capped.length ? capped : [{ json: { _empty: true, vertical: ctx.vertical, serp_warning: serpWarning } }];

// Flatten vertical results, drop markers, and cap the run - ROUND-ROBIN across
// verticals so one vertical can't crowd out the others under the cap.
const cfg = $('Run Config').first().json;
const all = $input.all().filter((i) => i.json && i.json.domain);
const byVertical = {};
for (const i of all) {
  (byVertical[i.json.vertical] = byVertical[i.json.vertical] || []).push(i);
}
const buckets = Object.values(byVertical);
const out = [];
let added = true;
while (out.length < cfg.maxNewPerRun && added) {
  added = false;
  for (const bucket of buckets) {
    if (out.length >= cfg.maxNewPerRun) break;
    const next = bucket.shift();
    if (next) { out.push(next); added = true; }
  }
}
return out;

// Minimal robots.txt check: honor a blanket "Disallow: /" for * or for us.
// Missing/unreachable robots.txt => allowed (standard convention).
const company = $('Per Company').first().json;
const resp = $input.first().json || {};
let allowed = true;
const txt = typeof resp === 'string' ? resp : (resp.data || resp.body || '');
if (!resp.error && typeof txt === 'string' && txt.length) {
  const lines = txt.split(/\r?\n/).map((l) => l.trim().toLowerCase());
  let applies = false;
  for (const line of lines) {
    if (line.startsWith('user-agent:')) {
      const agent = line.slice(11).trim();
      applies = agent === '*' || agent.includes('sanaku');
    } else if (applies && line.startsWith('disallow:')) {
      if (line.slice(9).trim() === '/') { allowed = false; break; }
    }
  }
}
return [{ json: { ...company, robots_allowed: allowed } }];

// Detect automation signals in the HTML, then score maturity + intent + tier.
const company = $('Check Robots').first().json;
const cfg = $('Run Config').first().json;
const resp = $input.first().json || {};
// n8n versions differ on where response text lands: body vs data.
let rawHtml = resp.body ?? resp.data ?? (typeof resp === 'string' ? resp : '');
if (rawHtml && typeof rawHtml === 'object') rawHtml = JSON.stringify(rawHtml);
const html = String(rawHtml || '').toLowerCase();
const headers = resp.headers || {};

// Category -> [name, regex] pairs. Names feed tech_stack; categories feed scoring.
const MARKERS = {
  chat: [
    ['Intercom', /widget\.intercom|intercomcdn|\bintercom\b/], ['Drift', /drift\.com|driftt\.com/],
    ['Tidio', /tidio/], ['Podium', /podiumwebchat|podium\.com/], ['Birdeye', /birdeye/],
    ['Ngage', /ngagelive|ngage\.com/], ['Smith.ai', /smith\.ai/], ['LiveChat', /livechatinc|livechat\.com/],
    ['Tawk.to', /tawk\.to/], ['ChatBot.com', /chatbot\.com|chatbotcdn/],
  ],
  booking: [
    ['Calendly', /calendly/], ['Acuity', /acuityscheduling/], ['Squarespace Scheduling', /squarespacescheduling|squarespace-scheduling/],
    ['YouCanBook.me', /youcanbook/], ['ServiceTitan', /servicetitan/], ['Housecall Pro', /housecallpro/],
    ['NexHealth', /nexhealth/], ['Zocdoc', /zocdoc/],
  ],
  crm: [
    ['HubSpot', /hs-scripts|hsforms|hubspot/], ['ActiveCampaign', /activecampaign|activehosted/],
    ['Klaviyo', /klaviyo/], ['Mailchimp', /mailchimp|chimpstatic|list-manage/],
    ['Clio Grow', /cliogrow|clio\.com/], ['Lawmatics', /lawmatics/], ['Filevine', /filevine/],
    ['Jobber', /getjobber|jobber\.com/],
  ],
  ads: [
    ['Google Ads tag', /googleadservices|gtag\(.{0,40}aw-|google_conversion/], ['Google Tag Manager', /googletagmanager/],
    ['Meta Pixel', /fbevents\.js|fbq\(/],
  ],
};

const techStack = [];
// Bot-walled or empty pages must NOT be scored - a Cloudflare challenge page
// has no widgets and would falsely read as "zero automation" (Tier 1 bait).
const blocked = html.length < 1500 ||
  /just a moment\.\.\.|attention required! \| cloudflare|cf-browser-verification|checking your browser before|enable javascript and cookies to continue/.test(html);
if (blocked) {
  return [{ json: {
    ...company,
    scored: true,
    qualified: false,
    blocked: true,
    ai_maturity_score: null,
    intent_score: null,
    tier: null,
    tech_stack: [],
    signals: { blocked: true, reason: 'site blocked automated fetch (' + html.length + ' bytes) - verify by hand before trusting any score' },
  } }];
}

const detected = {};
for (const [cat, pairs] of Object.entries(MARKERS)) {
  const hits = pairs.filter(([, re]) => re.test(html));
  if (hits.length) {
    detected[cat] = hits.map(([name]) => name);
    techStack.push(...hits.map(([name]) => name));
  }
}

const hasForm = /<form/.test(html);
const phoneVisible = /href="tel:|\(\d{3}\)\s?\d{3}[- .]\d{4}|\d{3}[-.]\d{3}[-.]\d{4}/.test(html);
const answerLanguage = /24\/7|24-7|we answer|answered? live|always (open|available)|available 24/.test(html);
const painKeywords = /call now|24\/7|free consultation|same[- ]day/.test(html);
const multiLocation = /(our|all|view) locations|locations<\/a>|serving .{0,40}(county|counties|areas)/.test(html);
const linkedinPresence = /linkedin\.com\/(in|company)\//.test(html);

const yearMatches = [...html.matchAll(/(?:\u00a9|&copy;|copyright)[^0-9]{0,20}(20\d{2})/g)].map((m) => Number(m[1]));
const copyrightYear = yearMatches.length ? Math.max(...yearMatches) : null;
let freshSite = copyrightYear !== null && copyrightYear >= cfg.currentYear - 1;
if (!freshSite && headers['last-modified']) {
  const age = (Date.now() - new Date(headers['last-modified']).getTime()) / 86400000;
  if (!Number.isNaN(age) && age <= 365) freshSite = true;
}

// Hard exclude: the site itself is an automation/marketing vendor.
if (/we build (ai|automation|chatbots)|marketing agency|lead generation (agency|company)|ai (agency|solutions for)/.test(html)) {
  return [{ json: { _excluded: true, domain: company.domain } }];
}

// --- AI maturity: 0 no automation (best) / 1 partial / 2 mature ---
let maturity = 0;
if (detected.chat) maturity = 2;
else if (detected.booking || detected.crm) maturity = 1;

// --- Intent 0-100 ---
let intent = 0;
const reasons = [];
if (detected.ads) { intent += 30; reasons.push('paying for ads (' + detected.ads.join(', ') + ')'); }
const emp = company.employee_count;
if (emp == null) { intent += 10; }  // size unknown (Places-sourced) - neutral credit, not a penalty
else if (emp >= 5 && emp <= 50) { intent += 20; reasons.push(emp + ' staff'); }
if ((company.review_count || 0) >= 25 && (company.rating || 0) >= 4.0) { intent += 15; reasons.push(company.review_count + ' Google reviews at ' + company.rating); }
if (freshSite) { intent += 10; reasons.push('site updated recently'); }
if (painKeywords) { intent += 10; reasons.push('pain language on site'); }
if (multiLocation) { intent += 10; reasons.push('multiple locations'); }
if (linkedinPresence) { intent += 5; }
intent = Math.min(100, intent);

if (maturity === 0) reasons.unshift('zero intake automation');
else if (maturity === 1) reasons.unshift('only basic tools (' + techStack.join(', ') + ')');

// --- Tier ---
let tier = 3;
if (maturity === 0 && intent >= 65) tier = 1;
else if (maturity <= 1 && intent >= 45 && intent <= 64) tier = 2;

// Scrape a contact email off the page (Places-sourced prospects have no Apollo contact).
const emailMatches = [...new Set([...html.matchAll(/[a-z0-9._%+-]+@[a-z0-9-]+(?:\.[a-z0-9-]+)*\.[a-z]{2,}/g)].map((m) => m[0]))]
  .filter((e) => !/\.(png|jpe?g|gif|svg|webp|css|js)$/.test(e) && !/no-?reply|sentry|wixpress|example\.|schema\.org|yourdomain|@email\.|adsadmin|godaddy|@[0-9.]+$|webcomponents|polyfill/.test(e));
const sameDomain = emailMatches.find((e) => e.endsWith('@' + company.domain));
const scrapedEmail = sameDomain || emailMatches[0] || null;

// Phone fallback: if Maps did not supply one, take it off their own site.
let scrapedPhone = null;
const telMatch = html.match(/href=\"tel:([+0-9()\-\. ]{7,20})\"/);
if (telMatch) scrapedPhone = telMatch[1].trim();
if (!scrapedPhone) {
  const m = html.match(/\(\d{3}\)\s?\d{3}[-. ]\d{4}|\b\d{3}[-.]\d{3}[-.]\d{4}\b/);
  if (m) scrapedPhone = m[0];
}

return [{ json: {
  ...company,
  contact_email: company.contact_email || scrapedEmail,
  contact_phone: company.contact_phone || scrapedPhone,
  // A tel: link on a homepage is the switchboard, never a direct line. Say so,
  // so the dashboard does not present it as the owner's number.
  company_phone: company.company_phone || scrapedPhone,
  contact_phone_source: company.contact_phone_source || (scrapedPhone ? 'website' : null),
  tech_stack: techStack,
  signals: {
    detected,
    has_contact_form: hasForm,
    phone_visible: phoneVisible,
    answer_language: answerLanguage,
    pain_keywords: painKeywords,
    multi_location: multiLocation,
    linkedin_on_site: linkedinPresence,
    copyright_year: copyrightYear,
    fresh_site: freshSite,
    rating: company.rating,
    review_count: company.review_count,
    reason: reasons.slice(0, 4).join('; '),
  },
  ai_maturity_score: maturity,
  intent_score: intent,
  tier,
  scored: true,
} }];

// Reveal decision-maker emails for prospects Apollo found, best intent first.
// HARD CAP: this is the only place in the workflow that spends Apollo credits.
//
// Tier 1 fills the cap first, then Tier 2. It used to be Tier 1 only, which
// silently wasted the difference: a run that turns up 5 Tier 1 prospects spent
// 5 of the 12 slots and left every Tier 2 prospect without an email - and W2's
// queue is filtered on contact_email IS NOT NULL, so those never get contacted
// at all. They just accumulate in the dashboard. Tier 3 is never revealed.
const cfg = $('Run Config').first().json;
const items = $input.all().map((i) => i.json);
// Within a tier, authority breaks the tie before intent does. Two prospects
// scoring the same, one an owner and one an office manager, are not equally
// worth a credit - the reveal buys a conversation, and only one of them can
// end it with a yes.
const RANK = { owner: 6, c_suite: 5, partner: 4, marketing: 3, leader: 2, staff: 1, none: 0 };
const byAuthorityThenIntent = (a, b) =>
  (RANK[b.contact_authority] || 0) - (RANK[a.contact_authority] || 0) ||
  b.intent_score - a.intent_score;
const byIntent = byAuthorityThenIntent;
const found = items.filter((x) => x.apollo_person_id);
const eligible = [
  ...found.filter((x) => x.tier === 1).sort(byIntent),
  ...found.filter((x) => x.tier === 2).sort(byIntent),
].slice(0, cfg.maxRevealsPerRun);
const revealSet = new Set(eligible.map((x) => x.domain));
return items.map((x) => ({ json: { ...x, needsReveal: revealSet.has(x.domain) } }));

// Attach the revealed business email (never personal) to the prospect.
const company = $('Per Reveal').first().json;
const resp = $input.first().json || {};
const person = resp.person || {};
const email = person.email && !String(person.email).includes('email_not_unlocked') ? person.email : null;

// The person's own number wins. This used to read
//   company.contact_phone || person.sanitized_phone
// so the org's main line, already set upstream, always won - and a reveal that
// DID return the decision maker's direct line was thrown away every time.
const direct = person.sanitized_phone || null;
return [{ json: {
  ...company,
  contact_email: email || company.contact_email || null,
  contact_phone: direct || company.contact_phone || null,
  contact_phone_source: direct ? 'apollo_direct' : (company.contact_phone_source || null),
  company_phone: company.company_phone || company.contact_phone || null,
  contact_linkedin_url: company.contact_linkedin_url || person.linkedin_url || null,
} }];

// The site refused our fetch (403 Cloudflare challenge, 404, timeout...).
// Keep the lead anyway using the Google Maps data - unscored, flagged for
// manual review. Losing a callable business because its site blocks bots
// would be the wrong trade.
const company = $('Per Company').first().json;
return [{ json: {
  ...company,
  scored: true,
  qualified: false,
  fetch_failed: true,
  ai_maturity_score: null,
  intent_score: null,
  tier: null,
  tech_stack: [],
  signals: {
    fetch_failed: true,
    rating: company.rating ?? null,
    review_count: company.review_count ?? null,
    reason: 'website blocked automated fetch - Google Maps data only; check the site by hand before calling'
  },
} }];
